var e={id:`avskriftene`,episode:21,door:21,title:{nb:`Avskriftene`,en:`The copies`},reference:`Luk 1,1–4`,place:`cesarea`,prologue:[{image:`maps/cesarea-torg.webp`,text:{nb:`Lukas lager én rull. Så kopierer noen den, og noen kopierer kopien. Hundre år fra nå: er det fortsatt hans ord?`,en:`Luke makes one scroll. Then someone copies it, and someone copies the copy. A hundred years from now: are they still his words?`}},{image:`art/lukas.webp`,text:{nb:`I Jakobs stue så du hva én uforsiktig skriver kan gjøre, og ingen avskrifter blir helt like. Hvordan finner man da tilbake til det Lukas skrev?`,en:`In James’s house you saw what one careless copyist can do, and no two copies come out quite alike. How, then, do you find the way back to what Luke wrote?`}}],intro:{nb:`Torget i Cæsarea, med skriverstua, boklageret og folk som handler.`,en:`The square in Caesarea, with the copying room, the book storeroom and people trading.`},outro:{nb:`Avskrivere gjør små, kjente feil. Mange avskrifter fra mange steder gjør ikke de samme feilene, og da kan man finne tilbake.`,en:`Copyists make small, known mistakes. Many copies from many places do not make the same ones, and so you can find the way back.`},map:[`################..##############`,`################..##############`,`##############....##############`,`#############.......############`,`############........############`,`#########......##.......########`,`##########.....###...###########`,`###########..........###########`,`###########.........############`,`######.#...###...##...##########`,`#####......###...##...##########`,`#####..#######...########.###..#`,`................................`,`..#.#..#.##..#....#..#..#..#.#..`,`########.##..#....#..#..########`,`#######..#############..########`,`#######..##############..#######`,`#######..##############..#######`,`#######..##############..#######`,`################################`,`################################`],background:`cesarea-torg.webp`,mood:`calm`,areas:[{id:`skriverstue`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######.....#########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`skrivestue.webp`,scale:1.8,ambience:`street`},{id:`boklager`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######......########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####.....................######`,`#####.....................######`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`verksted.webp`,scale:1.8,ambience:`street`}],start:{x:15,y:10},entities:[{id:`lukas`,kind:`person`,x:16,y:10,name:{nb:`Lukas`,en:`Luke`},look:`luke`,portrait:`lukas.webp`,interactions:[{not:[`oppdrag`],say:[{nb:`Snakk med avskriveren, læregutten, bokhandleren, den blinde og rabbien. Gå inn i skriverstua og boklageret.`,en:`Talk to the copyist, the apprentice, the bookseller, the blind man and the rabbi. Go into the copying room and the book storeroom.`}],set:[`oppdrag`]},{has:[`feiltyper-lost`,`mange-lost`,`homer-lost`,`tellerne-lost`,`husket-lost`,`veien-lost`],not:[`avsluttet`],say:[{nb:`Ordene mine vil overleve dem som kopierer meg, hvis det blir mange nok avskrifter. Og jeg skal skrive så tydelig at en endring synes.`,en:`My words will outlive those who copy me, if there are enough copies. And I will write so clearly that a change shows.`},{nb:`I morgen: lyset for hedningene, og mannen fra Roma som etterprøvde det jeg skriver.`,en:`Tomorrow: the light for the gentiles, and the man from Rome who tested what I write.`}],set:[`avsluttet`]},{has:[`spor:avskriver`],not:[`feiltyper-lost`],say:[{nb:`Sakene venter i vitneboka.`,en:`The cases are waiting in the notebook.`}]},{say:[{nb:`Avskriveren, læregutten, bokhandleren, den blinde, rabbien. Skriverstua og boklageret.`,en:`The copyist, the apprentice, the bookseller, the blind man, the rabbi. The copying room and the book storeroom.`}]}]},{id:`dor-skriverstue`,kind:`place`,x:14,y:2,name:{nb:`Skriverstua`,en:`The copying room`},look:`hotspot`,door:{area:`skriverstue`,x:15,y:14}},{id:`dor-boklager`,kind:`place`,x:25,y:11,name:{nb:`Boklageret`,en:`The book storeroom`},look:`hotspot`,door:{area:`boklager`,x:15,y:14}},{id:`avskriver`,kind:`person`,x:12,y:8,name:{nb:`Avskriveren`,en:`The copyist`},look:`scribe`,portrait:`scribe.webp`,interactions:[{has:[`oppdrag`],not:[`spor:avskriver`],say:[{nb:`Jeg kopierer for betaling: Homer, kontrakter, brev, og nå og da en av rullene deres. Jeg leser en linje, husker den, skriver den.`,en:`I copy for pay: Homer, contracts, letters, and now and then one of your scrolls. I read a line, remember it, write it.`},{nb:`Og der skjer feilene: øyet hopper fra ett ord til det samme ordet lenger nede, og en linje er borte. Eller jeg skriver samme ord to ganger.`,en:`That is where mistakes happen: the eye jumps to the same word further down, and a line is gone. Or I write a word twice.`},{nb:`Verst er det når noen leser høyt og flere skriver. Da hører man feil: ord som lyder likt.`,en:`Worst is when someone reads aloud and several write. Then you mishear: words that sound alike.`},{nb:`Og noen skrivere «retter» det de tror er feil i forelegget. Det er den farligste feilen, for den ser riktig ut.`,en:`And some scribes “correct” what they think is wrong in the exemplar. That is the most dangerous mistake, for it looks right.`}],set:[`spor:avskriver`,`spor:feilslag`,`fakta:feiltyper`]},{has:[`ark`],not:[`avskrift`],say:[{nb:`Paulus’ brev? Linje for linje, og så sammenligner jeg med forelegget. Ferdig. Ta det til bokhandleren.`,en:`Paul’s letter? Line by line, and then I compare it with the original. Done. Take it to the bookseller.`}],set:[`avskrift`]},{has:[`avskrift`],not:[`seglet-trykket`],say:[{nb:`Vent. Bokhandleren vil ha seglet mitt på avskriften, så kjøperen ser hvem som har skrevet og sammenlignet. Trykk det i voksen: tre rene avtrykk.`,en:`Wait. The bookseller wants my seal on the copy, so the buyer sees who wrote and compared it. Press it into the wax: three clean prints.`}],play:{game:`seal`,title:{nb:`Sett seglet på avskriften`,en:`Seal the copy`},win:`seglet-trykket`,data:{needed:3,presses:5}}},{not:[`oppdrag`],say:[{nb:`Snakk med Lukas først.`,en:`Speak with Luke first.`}]},{say:[{nb:`Øyet hopper. Øret hører feil. Hånden retter. Det er de tre.`,en:`The eye jumps. The ear mishears. The hand corrects. Those are the three.`}]}]},{id:`laeregutt`,kind:`person`,x:18,y:8,name:{nb:`Læregutten`,en:`The apprentice`},look:`boy`,portrait:`boy.webp`,interactions:[{has:[`oppdrag`],not:[`spor:laeregutt`],say:[{nb:`Mester sier: sammenlign alltid med forelegget etterpå, linje for linje. Har du to forelegg som ikke er like, skriv begge i margen, så kan den neste velge.`,en:`Master says: always compare with the exemplar afterwards, line by line. If you have two exemplars that differ, write both in the margin, so the next one can choose.`},{nb:`Jeg gjorde en feil i går; han fant den fordi han hadde en annen avskrift å holde min mot.`,en:`I made a mistake yesterday; he found it because he had another copy to hold mine against.`},{nb:`Vil du prøve? Jeg har skrevet av begynnelsen på Lukas’ rulle, og mester sier fire ord er feil. Finn dem, så ser du hvorfor han alltid sammenligner.`,en:`Do you want to try? I have copied the beginning of Luke’s scroll, and the master says four words are wrong. Find them, and you will see why he always compares.`}],set:[`spor:laeregutt`]},{say:[{nb:`Finn de fire ordene.`,en:`Find the four words.`}],play:{game:`copies`,title:{nb:`Finn de endrede ordene`,en:`Find the changed words`},data:{original:{nb:`Mange har forsøkt å gi en fremstilling av det som er blitt oppfylt blant oss, slik vi har fått det overlevert av dem som fra først av var øyenvitner.`,en:`Many have tried to write down what happened among us, as it was told to us by those who were eyewitnesses from the start.`},copy:{nb:`Noen har forsøkt å gi en fremstilling av det som er blitt glemt blant oss, slik vi har fått det diktet av dem som fra først av var reisende.`,en:`Some have tried to write down what vanished among us, as it was sold to us by those who were travellers from the start.`}},win:`spill-avskrift`,key:!0}}]},{id:`bokhandler`,kind:`person`,x:19,y:7,name:{nb:`Bokhandleren`,en:`The bookseller`},look:`trader`,portrait:`trader.webp`,interactions:[{has:[`oppdrag`],not:[`spor:bokhandler`],say:[{nb:`Homer selger best. Jeg har tre Iliader på lager, og ingen av dem er helt like. En linje ekstra her, et ord byttet der. Kjøperne bryr seg ikke.`,en:`Homer sells best. I have three Iliads in stock, and no two are quite alike. An extra line here, a word swapped there. The buyers do not care.`},{nb:`De lærde i Alexandria bryr seg: de har samlet avskrifter fra hele verden, sammenlignet dem og merket i margen der de tror en linje er lagt til.`,en:`The scholars in Alexandria do: they gather copies from all over the world, compare them and mark the margin where they think a line was added.`}],set:[`spor:bokhandler`,`fakta:homer`]},{has:[`avskrift`],not:[`avskrift-levert`],say:[{nb:`Nå finnes brevet i én by til.`,en:`Now the letter exists in one more city.`}],set:[`avskrift-levert`]},{say:[{nb:`Mange avskrifter. Se hvor de spriker.`,en:`Many copies. See where they diverge.`}]}]},{id:`blind`,kind:`person`,x:23,y:13,name:{nb:`Den blinde`,en:`The blind man`},look:`beggar`,portrait:`beggar.webp`,interactions:[{has:[`oppdrag`],not:[`spor:blind`],say:[{nb:`Jeg kan ikke lese. Jeg kan Salmene utenat, alle, og halve Jesaja. Slik lærte vi i synagogen: høre, gjenta, høre, gjenta.`,en:`I cannot read. I know the Psalms by heart, all of them, and half of Isaiah. That is how we learned in the synagogue: hear, repeat, hear, repeat.`},{nb:`Vi var mange som kunne det samme; sa én feil, rettet de andre ham.`,en:`Many of us knew the same; if one said it wrong, the others corrected him.`},{nb:`Ordene om Jesus går slik også. Jeg har hørt det samme fra Kapernaum og fra Jerusalem, med små forskjeller i rekkefølgen, men de samme ordene. Folk husker ord bedre enn du tror, skriver.`,en:`The words about Jesus go that way too. I have heard the same from Capernaum and from Jerusalem, with small differences in the order, but the same words. People remember words better than you think, writer.`}],set:[`spor:blind`,`fakta:muntlig`]},{say:[{nb:`Høre, gjenta. Mange som kan det samme.`,en:`Hear, repeat. Many who know the same.`}]}]},{id:`rabbi`,kind:`person`,x:12,y:4,name:{nb:`Rabbien`,en:`The rabbi`},look:`scribe`,portrait:`scribe.webp`,interactions:[{has:[`oppdrag`],not:[`spor:rabbi`],say:[{nb:`Når vi kopierer loven, gransker vi hver bokstav, og noen av oss teller: bokstavene i kolonnen, ordene, linjene, så vi kan merke om noe mangler.`,en:`When we copy the law, we check every letter, and some of us count the letters, words and lines, so we know if something is missing.`},{nb:`Mangler det én bokstav, er rullen ubrukelig.`,en:`If one letter is missing, the scroll is unusable.`},{nb:`Dere kristne kopierer fortere og billigere, hører jeg. Da får dere flere feil. Men dere får også flere avskrifter.`,en:`You Christians copy faster and cheaper, I hear. Then you get more mistakes. But you also get more copies.`}],set:[`spor:rabbi`,`fakta:tellere`]},{say:[{nb:`Tell bokstavene. Alltid.`,en:`Count the letters. Always.`}]}]},{id:`jente`,kind:`person`,x:14,y:6,name:{nb:`Jenta`,en:`The girl`},look:`girl`,portrait:`girl.webp`,interactions:[{say:[{nb:`Jeg skriver bokstaver i sanden til jeg kan dem. Mor sier jeg hopper over linjer når jeg leser. Avskriveren sier det gjør alle.`,en:`I write letters in the sand until I know them. Mother says I skip lines when I read. The copyist says everyone does.`}],set:[`spor:jente`]}]},{id:`soldat`,kind:`person`,x:26,y:13,name:{nb:`Soldaten`,en:`The soldier`},look:`soldier`,portrait:`soldier.webp`,interactions:[{say:[{nb:`Ordre skrives på vokstavler og kopieres til hver avdeling. Én gang ble «ikke» borte på veien. Det ble en lang dag.`,en:`Orders are written on wax tablets and copied to each unit. Once the word “not” got lost on the way. It was a long day.`},{nb:`Begge tavlene ligger her ennå, ordren og avskriften. Se selv.`,en:`Both tablets are still here, the order and the copy. See for yourself.`}],set:[`spor:soldat`],has:[],not:[`spor:soldat`]},{has:[`spor:ordre-a`,`spor:ordre-b`],not:[`ordrene-sammenlignet`],say:[{nb:`Der. Ett ord. Øyet hoppet, og vi rykket fram.`,en:`There. One word. The eye skipped, and we advanced.`}],set:[`ordrene-sammenlignet`]},{say:[{nb:`Ett ord borte. En lang dag.`,en:`One word gone. A long day.`}],has:[],not:[],set:[]}]},{id:`papyrus`,kind:`thing`,x:16,y:7,name:{nb:`Papyrusbunten`,en:`The papyrus bundle`},look:`hotspot`,interactions:[{has:[`spor:bokhandler`],not:[`ark`],say:[{nb:`Fra Egypt. Den varer noen tiår, kanskje et par hundre år, i vanlig luft, og hundrevis av år i ørkensand.`,en:`From Egypt. It lasts a few decades, perhaps a couple of centuries, in ordinary air, and hundreds of years in desert sand.`},{nb:`Et ark kan bli en avskrift av Paulus’ brev til bokhandleren. Du tar et med til avskriveren.`,en:`A sheet could become a copy of Paul’s letter for the bookseller. You take one to the copyist.`}],set:[`ark`,`spor:papyrus`]},{say:[{nb:`Ark av papyrus fra Egypt, rimelig og lett. Varer noen tiår, kanskje et par hundre år, i vanlig luft, hundrevis av år i ørkensand. Det de skriver på i Egypt, kan graves opp lenge etter.`,en:`Sheets of papyrus from Egypt, cheap and light. Lasts a few decades, perhaps a couple of centuries, in ordinary air, hundreds of years in desert sand. What they write on in Egypt can be dug up long after.`}],set:[`spor:papyrus`]}]},{id:`vei-jerusalem`,kind:`place`,x:31,y:12,name:{nb:`Veien til Jerusalem`,en:`The road to Jerusalem`},look:`hotspot`,travelTo:`jerusalem`},{id:`vei-havna`,kind:`place`,x:0,y:12,name:{nb:`Til dagen da kureren kom`,en:`To the day the courier came`},look:`hotspot`,travel:`lukas-og-matteus`},{id:`dor-ut-skriverstue`,kind:`place`,x:15,y:17,name:{nb:`Ut på torget`,en:`Out to the square`},look:`hotspot`,door:{area:`main`,x:15,y:2},area:`skriverstue`},{id:`forelegg`,kind:`thing`,x:16,y:9,name:{nb:`Forelegget og avskriften`,en:`The exemplar and the copy`},look:`hotspot`,interactions:[{say:[{nb:`To ruller side om side, med en linjal på tvers. Avskriveren går linje for linje. I avskriften mangler en hel linje: øyet hoppet fra «og han sa» til neste «og han sa».`,en:`Two scrolls side by side, with a ruler across. The copyist goes line by line. In the copy a whole line is missing: the eye jumped from “and he said” to the next “and he said”.`}],set:[`spor:forelegg`]}],area:`skriverstue`},{id:`margnotat`,kind:`thing`,x:19,y:9,name:{nb:`Margnotatet`,en:`The marginal note`},look:`hotspot`,interactions:[{say:[{nb:`I margen på en avskrift står et ord med en liten strek: en leser har «rettet» teksten. Neste avskriver kan ta det inn i linja, og da er det ingen som ser at det var en rettelse.`,en:`In a copy’s margin, a word with a small stroke: a reader has “corrected” the text. The next copyist may put it into the line, and then nobody can tell.`}],set:[`spor:margnotat`]}],area:`skriverstue`},{id:`diktat`,kind:`thing`,x:13,y:9,name:{nb:`Diktatbenken`,en:`The dictation bench`},look:`hotspot`,interactions:[{say:[{nb:`Fem seter på rad foran en lesepult. Noen verksteder lar én lese høyt mens flere skriver. Da hører alle feil på samme sted: «dere» og «vi» begynner å lyde likt på gresk.`,en:`Five seats in a row before a reading desk. Some workshops let one read aloud while several write. Then all mishear at the same place: “you” and “we” are beginning to sound alike in Greek.`}],set:[`spor:diktat`]}],area:`skriverstue`},{id:`notat`,kind:`thing`,x:22,y:7,name:{nb:`Lukas’ notat`,en:`Luke’s note`},look:`hotspot`,interactions:[{say:[{nb:`Et ark: «Tre slags feil: øyet, øret, hånden. Alle små; ingen gjør en toller til en konge eller flytter Betlehem. Mange avskrifter fra mange steder gjør ikke de samme feilene.»`,en:`A sheet: “Three kinds of mistakes: the eye, the ear, the hand. All small; none turns a tax collector into a king or moves Bethlehem. Many copies from many places do not share the same mistakes.”`}],set:[`spor:notat`]}],area:`skriverstue`},{id:`dor-ut-boklager`,kind:`place`,x:15,y:17,name:{nb:`Ut på torget`,en:`Out to the square`},look:`hotspot`,door:{area:`main`,x:25,y:12},area:`boklager`},{id:`iliader`,kind:`thing`,x:5,y:10,name:{nb:`De tre Iliadene`,en:`The three Iliads`},look:`hotspot`,interactions:[{say:[{nb:`Tre ruller av Iliaden. Samme sted i alle tre: den ene har en linje ekstra, de to andre har den ikke.`,en:`Three scrolls of the Iliad. The same place in all three: one has an extra line, the other two do not.`},{nb:`Når to av tre er enige, og linja ser ut som den er hentet fra et annet sted i diktet, vet du hvilken som er feil.`,en:`When two of three agree, and the line looks as if it were taken from another place in the poem, you know which one is wrong.`}],set:[`spor:iliader`]}],area:`boklager`},{id:`alexandria`,kind:`thing`,x:26,y:10,name:{nb:`Merkene fra Alexandria`,en:`The marks from Alexandria`},look:`hotspot`,interactions:[{say:[{nb:`En Homer-rull med små tegn i margen, slik de lærde i Alexandria setter dem: en strek for «trolig tilføyd», en annen for «flyttet». De sletter ikke; de merker, så leseren kan dømme selv.`,en:`A Homer scroll with small signs in the margin, as the scholars in Alexandria set them: a stroke for “probably added”, another for “moved”. They do not delete; they mark, so the reader can judge for himself.`}],set:[`spor:alexandria`]}],area:`boklager`},{id:`lovrull`,kind:`thing`,x:13,y:9,name:{nb:`Lovrullen`,en:`The law scroll`},look:`hotspot`,interactions:[{say:[{nb:`En rull med loven, skrevet av en sofer. Hver kolonne har like mange linjer, og hver bokstav er gransket. Ikke en flekk, ikke en rettelse. Slike ruller ser like ut hundre år fra hverandre.`,en:`A scroll of the law, written by a sofer. Every column has the same number of lines, and every letter has been examined. Not a blot, not a correction. Such scrolls look alike a hundred years apart.`}],set:[`spor:lovrull`]}],area:`boklager`},{id:`brev`,kind:`thing`,x:18,y:9,name:{nb:`Paulus’ brev`,en:`Paul’s letter`},look:`hotspot`,interactions:[{say:[{nb:`En avskrift av et brev Paulus sendte til Korint. Der skriver han at han ga videre det han selv hadde fått overlevert: at Jesus døde, ble begravet, sto opp og viste seg for mange.`,en:`A copy of a letter Paul sent to Corinth. In it he writes that he handed on what he himself had received: that Jesus died, was buried, rose and appeared to many.`},{nb:`Menigheten leste det høyt, kopierte det og sendte avskrifter videre. Brevet finnes alt i flere byer. Den som ville endre det, måtte endre alle.`,en:`The church there read it aloud, copied it and sent copies on. It is already in several cities; anyone who wanted to change it would have to change them all.`}],set:[`spor:brev`]}],area:`boklager`},{id:`ordre-original`,kind:`thing`,x:7,y:16,name:{nb:`Ordretavla`,en:`The order tablet`},look:`hotspot`,interactions:[{say:[{nb:`Soldatens tavle: «Rykk IKKE fram før daggry.»`,en:`The soldier’s tablet: “Do NOT advance before dawn.”`}],set:[`spor:ordre-a`]}]},{id:`ordre-kopi`,kind:`thing`,x:24,y:16,name:{nb:`Avskriften av ordren`,en:`The copy of the order`},look:`hotspot`,interactions:[{say:[{nb:`Avskriften: «Rykk fram før daggry.»`,en:`The copy: “Advance before dawn.”`}],set:[`spor:ordre-b`]}]},{id:`leke-baat`,kind:`thing`,x:24,y:17,name:{nb:`Båten ved brygga`,en:`The boat by the jetty`},look:`hotspot`,interactions:[{say:[{nb:`Båten vugger så det skvulper. Godt at avskriveren ikke satt her med blekket sitt.`,en:`The boat rocks until the water slops over. Good thing the copyist wasn’t sitting here with his ink.`}],fx:`rock`}]},{id:`leke-frukt`,kind:`thing`,x:13,y:3,name:{nb:`Fruktboden`,en:`The fruit stall`},look:`hotspot`,interactions:[{say:[{nb:`Fikenene triller. Selgeren teller mens hun plukker: «… nittiåtte, nittini … én mangler!»`,en:`The figs roll away. The seller counts as she picks them up: “… ninety-eight, ninety-nine … one is missing!”`},{nb:`Hun er nesten like nøye som rabbien.`,en:`She is almost as careful as the rabbi.`}],fx:`tip`}]},{id:`leke-skaal`,kind:`thing`,x:14,y:13,name:{nb:`Bronseskåla`,en:`The bronze bowl`},look:`hotspot`,interactions:[{say:[{nb:`Den blinde snur seg mot lyden: «Bronse. Gammel. Og noen slo på den med vilje.»`,en:`The blind man turns towards the sound: “Bronze. Old. And someone struck it on purpose.”`}],fx:`ring`}]},{id:`leke-vinde`,kind:`thing`,x:17,y:5,name:{nb:`Brønnvinda`,en:`The well windlass`},look:`hotspot`,interactions:[{say:[{nb:`Vinda knirker rundt, og bøtta går ned i brønnen. Det tar lang tid før du hører vannet.`,en:`The windlass creaks round and the bucket goes down the well. It takes a long time before you hear the water.`}],fx:`spin`}]},{id:`leke-palme`,kind:`thing`,x:17,y:2,name:{nb:`Palmen`,en:`The palm tree`},look:`hotspot`,interactions:[{say:[{nb:`Bladene rasler som tørr papyrus. En daddel treffer deg midt i panna.`,en:`The fronds rustle like dry papyrus. A date hits you right in the middle of the forehead.`}],fx:`shake`}]}],facts:[{id:`feiltyper`,title:{nb:`Avskriverfeil`,en:`Scribal errors`},body:{nb:`Kort sagt: Avskrivere gjorde små, kjente feil, og de fleste av de 400 000 forskjellene er stavemåter og ordstilling. Tekstforskere kjenner avskrivernes feil godt. Øyet hopper fra ett ord til et likt ord lenger ned (parablepsis, ofte ved like linjeslutt), skriver én gang det som sto to ganger (haplografi) eller dobler (dittografi). Øret hører likt-lydende ord feil ved diktat (på gresk lød «dere» og «vi», hymeis og hēmeis, nesten likt); slike feil oppsto også når skriveren «hørte» ordet inni seg mens han leste. Om avskrifter ble laget ved høytlesning for flere skrivere, er omstridt; de fleste avskrifter ble gjort av én skriver med forelegget foran seg. Og hånden «retter», eller tar margnotater inn i teksten. Det aller meste av de rundt 400 000 variantene i de greske håndskriftene til Det nye testamente er av dette slaget: stavemåter, ordstilling, småord. Noen, som Bart Ehrman, bruker tallet 400 000 til å si at vi ikke kan vite hva originalene sa. Men tallet teller hver forskjell i hvert håndskrift, så flere håndskrifter gir automatisk flere varianter, og Ehrman sier selv at de aller fleste er ubetydelige. Det ærlige er å si: ingen sentral kristen lære står eller faller med én omstridt lesning; hvert lærepunkt har andre steder å stå på. Et eksempel: setningen om «tre som vitner i himmelen» (1 Joh 5,7–8) ble lenge brukt om treenigheten, men står ikke i de gamle greske håndskriftene, og treenighetslæren klarer seg uten den.`,en:`In short, copyists made small, well-known slips, and most of the 400,000 differences are spellings and word order. Textual scholars know the copyists’ mistakes well. The eye jumps from one word to a like word further down (parablepsis, often at similar line endings), writes once what stood twice (haplography) or doubles (dittography). The ear mishears similar-sounding words at dictation (in Greek “you” and “we”, hymeis and hēmeis, sounded nearly alike); such mistakes also arose when the copyist “heard” the word inside himself as he read. Whether copies were made by reading aloud to several scribes is disputed; most copies were made by one scribe with the exemplar in front of him. And the hand “corrects”, or takes marginal notes into the text. The vast majority of the roughly 400,000 variants in the Greek manuscripts of the New Testament are of this kind: spellings, word order, small words. Some, like Bart Ehrman, use the figure 400,000 to say we cannot know what the originals said. But the figure counts every difference in every manuscript, so more manuscripts automatically give more variants, and Ehrman himself says the vast majority are insignificant. The honest thing to say is: no central Christian doctrine stands or falls with a single disputed reading; every point of doctrine has other places to stand on. An example: the sentence about “three that bear witness in heaven” (1 John 5:7–8) was long used of the Trinity, but is not in the old Greek manuscripts, and the doctrine of the Trinity manages without it.`},unlockedBy:`fakta:feiltyper`,link:`https://bibleproject.com/videos/what-is-bible/`},{id:`mange`,title:{nb:`Mange avskrifter`,en:`Many copies`},body:{nb:`Kort sagt: Vi har flere tusen gamle avskrifter, og nettopp derfor kan vi sammenligne dem og finne feilene. Det nye testamente er den best bevitnede teksten fra antikken: rundt 5 800 registrerte greske håndskrifter (fra små fragmenter til hele bibler; noen er dobbeltført eller gått tapt), rundt 10 000 latinske og tusener på andre språk, pluss sitater hos kirkefedrene. Til sammenligning: Tacitus’ Annaler finnes i noen få håndskrifter fra 800–1000-tallet, Homer i omkring 1 800. Det eldste fragmentet, P52 med noen vers fra Johannes, er fra omkring år 125–175; P75 med store deler av Lukas fra omkring 200, kanskje noe senere. Nettopp fordi det er så mange, finner vi så mange varianter; og nettopp derfor kan vi sortere dem. To innvendinger må nevnes. De eldste håndskriftene er nesten alle fra Egypt, fordi papyrus bare overlever i ørkenen; vi ser altså de første hundreårene gjennom én landsdel. Men Egypt sto i samband med hele Middelhavet, og de egyptiske papyrene stemmer med senere avskrifter fra andre steder (Vatikan-håndskriftet, de gamle latinske og syriske oversettelsene). Og det er et hull: fra originalene til de første brukbare avskriftene går det godt over hundre år. En endring gjort før avskriftene spredte seg, ville alle ha arvet. Svaret er at vi alt på 100-tallet har flere uavhengige strømmer av tekst som er ulike i det små og like i det store; de forgrenet seg tidlig.`,en:`In short, we have thousands of old copies, and that is exactly why we can compare them and find the slips. The New Testament is the best attested text from antiquity: around 5,800 catalogued Greek manuscripts (some are double entries or lost) (from small fragments to whole Bibles), around 10,000 Latin and thousands in other languages, plus quotations in the church fathers. By comparison: Tacitus’ Annals survive in a few manuscripts from the the ninth to eleventh centuries, Homer in about 1,800. The oldest fragment, P52 with a few verses of John, is from around 125–175; P75 with large parts of Luke from around 200, perhaps somewhat later. Precisely because there are so many, we find so many variants; and precisely for that reason we can sort them. Two objections must be mentioned. The oldest manuscripts are nearly all from Egypt, because papyrus survives only in the desert; so we see the first centuries through one region. But Egypt was in touch with the whole Mediterranean, and the Egyptian papyri agree with later copies from elsewhere (the Vatican manuscript, the old Latin and Syriac translations). And there is a gap: from the originals to the first usable copies well over a hundred years pass. A change made before the copies spread would have been inherited by all. The answer is that as early as the second century we have several independent streams of text that differ in small things and agree in big ones; they branched early.`},unlockedBy:`mange-lost`},{id:`homer`,title:{nb:`Homer i Alexandria`,en:`Homer in Alexandria`},body:{nb:`Biblioteket i Alexandria samlet fra 200-tallet f.Kr. Homer-avskrifter fra hele den greske verden. Lærde som Zenodotos, Aristofanes fra Bysants og Aristarkos sammenlignet dem og satte kritiske tegn i margen (obelos for «trolig uekte») uten å slette noe. Det er begynnelsen på tekstkritikken, håndverket som senere ble brukt på Bibelen. Det nye testamente er behandlet med de samme redskapene som Homer og Platon, og er langt bedre bevitnet enn noen av dem.`,en:`The library of Alexandria gathered copies of Homer from the whole Greek world from the third century BC onward. Scholars such as Zenodotus, Aristophanes of Byzantium and Aristarchus compared them and set critical signs in the margin (the obelus for “probably spurious”) without deleting anything. That is the beginning of textual criticism, the craft later used on the Bible. The New Testament is treated with the same tools as Homer and Plato, and is far better attested than any of them.`},unlockedBy:`fakta:homer`},{id:`tellere`,title:{nb:`Tellerne`,en:`The counters`},body:{nb:`Kort sagt: Jødiske skrivere talte bokstavene, og Jesaja-rullen fra Qumran viser at det virket. Jødiske skrivere het soferim, «skrivere»; Talmud forklarer navnet med at de «talte» bokstavene (b. Kiddusjin 30a). Tellingen av bokstaver og ord og merkingen av midtpunktet i hver bok er best kjent fra masoretene (500–900-tallet), men Talmud fører skikken tilbake til de tidlige skriverne. Dødehavsrullene (ca. 250 f.Kr.–68 e.Kr.) viste hvor godt det virket: Jesaja-rullen fra Qumran er over tusen år eldre enn de middelalderske hebraiske håndskriftene man før hadde, og teksten er i det vesentlige den samme (de fleste forskjellene er stavemåter). Samtidig viser andre Qumran-ruller, som Jeremia og Samuel, at det fantes flere tekstformer side om side før år 70; den ene rene teksten kom senere. Kristne kopierte oftere og billigere, ofte med ulærte hender og tidlig i kodeks (bokform); det ga flere småfeil, men langt flere avskrifter.`,en:`In short, Jewish scribes counted the letters, and the Isaiah scroll from Qumran shows it worked. Jewish scribes were called soferim, “writers”; the Talmud explains the name by saying they “counted” the letters (b. Kiddushin 30a). The counting of letters and words and the marking of each book’s midpoint is best known from the Masoretes (the sixth to tenth centuries), but the Talmud traces the custom back to the early scribes. The Dead Sea Scrolls (c. 250 BC–AD 68) showed how well it worked: the Isaiah scroll from Qumran is over a thousand years older than the medieval Hebrew manuscripts previously known, and the text is essentially the same (most differences are spellings). At the same time other Qumran scrolls, such as Jeremiah and Samuel, show that several text forms existed side by side before AD 70; the one clean text came later. Christians copied more often and more cheaply, often with untrained hands and early on in codex (book form); that gave more small errors, but far more copies.`},unlockedBy:`fakta:tellere`},{id:`muntlig`,title:{nb:`Muntlig overlevering`,en:`Oral tradition`},body:{nb:`I antikken lærte man tekster utenat i stort omfang; rabbinske elever kunne hele Toraen. Forskere som Kenneth Bailey (som bodde i landsbyer i Midtøsten) og Richard Bauckham beskriver en «kontrollert» muntlig overlevering: fellesskapet retter den som forteller feil, kjernen og nøkkelordene er faste, mens rekkefølge og småord kan variere. Det passer med det vi ser i evangeliene: samme ord med små variasjoner. Og de første avskriftene ble laget mens øyenvitner ennå levde; Paulus ber om at brev byttes mellom menigheter (Kol 4,16), og omkring år 96 siterer Klemens i Roma Paulus’ første brev til Korint; det skrevne spredte seg fort. Baileys modell er omstridt (Theodore Weeden), men hovedtrekket, at fellesskapet retter fortelleren, er bredt anerkjent.`,en:`In antiquity texts were learned by heart on a large scale; rabbinic students knew the whole Torah by heart. Scholars such as Kenneth Bailey (who lived in Middle Eastern villages) and Richard Bauckham describe a “controlled” oral tradition: the community corrects the one who tells it wrong, the core and the key words are fixed, while order and small words may vary. That fits what we see in the Gospels: the same words with small variations. And the first copies were made while eyewitnesses were still alive; Paul asks for letters to be exchanged between churches (Col 4:16), and around AD 96 Clement in Rome quotes Paul’s first letter to Corinth; the written word spread fast. Bailey’s model is disputed (Theodore Weeden), but its main point, that the community corrects the teller, is widely accepted.`},unlockedBy:`fakta:muntlig`},{id:`omstridt`,title:{nb:`De kjente usikre stedene`,en:`The known uncertain places`},body:{nb:`Noen få lengre avsnitt er omstridt, og moderne bibler sier fra i klammer eller noter: den lange slutten på Markus (16,9–20), kvinnen grepet i ekteskapsbrudd (Joh 7,53–8,11), og hos Lukas svetten som blod (22,43–44) og ordene «Far, tilgi dem» (23,34), som mangler i noen tidlige håndskrifter. Det er nettopp fordi forskerne er ærlige om dette at vi kan stole på resten. Det finnes mange flere små usikre steder enn Bibelens noter viser, men de gjelder ordstilling, stavemåter og enkeltord, og de endrer ikke hva et avsnitt sier.`,en:`A few longer passages are disputed, and modern Bibles say so in brackets or notes: the long ending of Mark (16:9–20), the woman caught in adultery (John 7:53–8:11), and in Luke the sweat like blood (22:43–44) and the words “Father, forgive them” (23:34), which are missing in some early manuscripts. It is precisely because scholars are honest about this that we can trust the rest. There are many more small uncertain places than a Bible’s notes show, but they concern word order, spellings and single words, and they do not change what a passage says.`},unlockedBy:`veien-lost`},{id:`diktet`,title:{nb:`Hva er funnet på i denne episoden?`,en:`What is made up in this episode?`},unlockedBy:`veien-lost`,body:{nb:`Avskriveren, læregutten, bokhandleren, den blinde, rabbien, jenta og soldaten er funnet på, og det samme er det de sier. Skriverstua, boklageret, ordretavlene og Lukas’ notat er laget for spillet. Feiltypene, tellingen og merkene fra Alexandria bygger på det vi vet om skrivere i antikken. Hvordan Lukas’ rulle ble kopiert de første årene, vet vi ikke; en av de eldste avskriftene av Lukas, P75, er fra omkring år 200.`,en:`The copyist, the apprentice, the bookseller, the blind man, the rabbi, the girl and the soldier are invented, and so is what they say. The copying room, the book store, the order tablets and Luke’s note are made for the game. The kinds of error, the counting and the marks from Alexandria build on what we know about scribes in antiquity. How Luke’s scroll was copied in the first years, we do not know; one of the oldest copies of Luke, P75, is from around AD 200.`}}],clues:[{id:`avskriver`,source:{nb:`Avskriveren`,en:`The copyist`},text:{nb:`Leser en linje, husker, skriver. Øyet hopper mellom like ord, dobler ord. Ved diktat hører man feil.`,en:`Reads a line, remembers, writes. The eye jumps between like words, doubles words. At dictation one mishears.`},unlockedBy:`spor:avskriver`},{id:`feilslag`,source:{nb:`Avskriveren`,en:`The copyist`},text:{nb:`Den farligste feilen: skriveren «retter» det han tror er feil i forelegget. Den ser riktig ut.`,en:`The most dangerous mistake: the scribe “corrects” what he thinks is wrong in the exemplar. It looks right.`},unlockedBy:`spor:feilslag`},{id:`laeregutt`,source:{nb:`Læregutten`,en:`The apprentice`},text:{nb:`Sammenlign med forelegget etterpå. To ulike forelegg: skriv begge i margen. Feilen hans ble funnet mot en annen avskrift.`,en:`Compare with the exemplar afterwards. Two different exemplars: write both in the margin. His mistake was found against another copy.`},unlockedBy:`spill-avskrift`},{id:`bokhandler`,source:{nb:`Bokhandleren`,en:`The bookseller`},text:{nb:`Tre Iliader, ingen helt like. De lærde i Alexandria samler avskrifter fra hele verden og merker i margen der de tror en linje er lagt til.`,en:`Three Iliads, no two quite alike. The scholars in Alexandria gather copies from all over the world and mark in the margin where they think a line has been added.`},unlockedBy:`spor:bokhandler`},{id:`blind`,source:{nb:`Den blinde`,en:`The blind man`},text:{nb:`Kan Salmene utenat: høre, gjenta. Mange som kan det samme retter hverandre. Ordene om Jesus går likt i Kapernaum og Jerusalem, med små forskjeller i rekkefølgen.`,en:`Knows the Psalms by heart: hear, repeat. Many who know the same correct each other. The words about Jesus are the same in Capernaum and Jerusalem, with small differences in order.`},unlockedBy:`spor:blind`},{id:`rabbi`,source:{nb:`Rabbien`,en:`The rabbi`},text:{nb:`Loven kopieres bokstav for bokstav; noen teller bokstaver, ord og linjer for å merke om noe mangler. Kristne kopierer fortere: flere feil, men flere avskrifter.`,en:`The law is copied letter by letter; some count letters, words and lines to tell if something is missing. Christians copy faster: more mistakes, but more copies.`},unlockedBy:`spor:rabbi`},{id:`forelegg`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`I avskriften mangler en hel linje: øyet hoppet fra «og han sa» til neste «og han sa».`,en:`In the copy a whole line is missing: the eye jumped from “and he said” to the next “and he said”.`},unlockedBy:`spor:forelegg`},{id:`margnotat`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`Et ord i margen med en strek; neste avskriver kan ta det inn i linja.`,en:`A word in the margin with a stroke; the next copyist may take it into the line.`},unlockedBy:`spor:margnotat`},{id:`diktat`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`Én leser, fem skriver. Fem avskrifter med samme hørefeil: «dere» og «vi» begynner å lyde likt.`,en:`One reads, five write. Five copies with the same mishearing: “you” and “we” are beginning to sound alike.`},unlockedBy:`spor:diktat`},{id:`notat`,source:{nb:`Lukas’ notat`,en:`Luke’s note`},text:{nb:`Tre slags feil: øye, øre, hånd. Alle små; ingen gjør en toller til en konge. Mange avskrifter fra mange steder gjør ikke de samme feilene.`,en:`Three kinds of mistakes: eye, ear, hand. All small; none turns a tax collector into a king. Many copies from many places do not make the same mistakes.`},unlockedBy:`spor:notat`},{id:`iliader`,source:{nb:`De tre Iliadene`,en:`The three Iliads`},text:{nb:`Én har en linje ekstra, to har den ikke, og linja ser hentet fra et annet sted. Da vet man hvilken som er feil.`,en:`One has an extra line, two do not, and the line looks taken from another place. Then one knows which is wrong.`},unlockedBy:`spor:iliader`},{id:`alexandria`,source:{nb:`Merkene fra Alexandria`,en:`The marks from Alexandria`},text:{nb:`De lærde sletter ikke; de merker «trolig tilføyd» i margen, så leseren kan dømme.`,en:`The scholars do not delete; they mark “probably added” in the margin, so the reader can judge.`},unlockedBy:`spor:alexandria`},{id:`lovrull`,source:{nb:`Lovrullen`,en:`The law scroll`},text:{nb:`Skrevet av en sofer: like mange linjer i hver kolonne, hver bokstav gransket, ingen rettelser.`,en:`Written by a sofer: the same number of lines in every column, every letter examined, no corrections.`},unlockedBy:`spor:lovrull`},{id:`brev`,source:{nb:`Paulus’ brev`,en:`Paul’s letter`},text:{nb:`Paulus ga videre det han selv hadde fått overlevert om Jesus. Brevet til Korint ble lest høyt, kopiert og sendt videre; det finnes alt i flere byer.`,en:`Paul handed on what he himself had received about Jesus. The letter to Corinth was read aloud, copied and sent on; it already exists in several cities.`},unlockedBy:`spor:brev`},{id:`papyrus`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`Papyrus varer noen tiår, kanskje et par hundre år, i vanlig luft, hundrevis av år i ørkensand.`,en:`Papyrus lasts a few decades, perhaps a couple of centuries, in ordinary air, hundreds of years in desert sand.`},unlockedBy:`spor:papyrus`}],deductions:[{id:`feiltyper`,question:{nb:`Hva slags feil gjør avskrivere?`,en:`What kinds of mistakes do copyists make?`},clues:[`avskriver`,`feilslag`,`forelegg`,`diktat`,`margnotat`],steps:[{ask:{nb:`Hva sa avskriveren om feilene sine?`,en:`What did the copyist say about his mistakes?`},clues:[`avskriver`,`feilslag`],yes:{nb:`Øyet hopper, øret hører feil, hånden retter. Hva så du i skriverstua?`,en:`The eye jumps, the ear mishears, the hand corrects. What did you see in the copying room?`},no:{nb:`Det er ikke avskriveren.`,en:`That is not the copyist.`}},{ask:{nb:`Hva så du i skriverstua?`,en:`What did you see in the copying room?`},clues:[`forelegg`,`diktat`,`margnotat`],yes:{nb:`En linje borte, fem like hørefeil, et ord i margen. Hva slags feil er det?`,en:`A line gone, the same mishearing five times, a word in the margin. What kinds of mistakes are those?`},no:{nb:`Det handler ikke om det du så i skriverstua.`,en:`That is not about what you saw in the copying room.`}}],options:[{text:{nb:`Øyet hopper, øret hører feil, og hånden «retter»: små feil som lar seg oppdage`,en:`The eye jumps, the ear mishears, the hand “corrects”: small slips that can be found`},feedback:{nb:`Riktig. Øyet hopper, øret hører feil, hånden tar margnotater inn i teksten. Men ingen av dem flytter Betlehem eller gjør Pilatus til Herodes: småfeil, ikke nye fortellinger.`,en:`Correct. The eye jumps, the ear mishears, the hand takes margin notes into the text. But none of them moves Bethlehem or turns Pilate into Herod: small mistakes, not new stories.`},correct:!0},{text:{nb:`Avskrivere dikter om hele fortellingen, så den passer bedre til det folk vil høre i deres by`,en:`Copyists rewrite the whole story so it fits better with what people in their city want to hear`},feedback:{nb:`Nei. Hør avskriveren: han leser en linje og skriver den. Feilene er på ord- og linjenivå, og den som endrer med vilje, blir avslørt av de andre avskriftene.`,en:`No. Listen to the copyist: he reads a line and writes it. The mistakes are at word and line level, and whoever changes on purpose is exposed by the other copies.`}},{text:{nb:`Avskrivere gjør ingen feil`,en:`Copyists make no mistakes`},feedback:{nb:`Jo. Se forelegget: en hel linje borte, enda han sammenligner. Det skjer hver dag, og noe slipper gjennom.`,en:`They do. Look at the exemplar: a whole line gone, even though he compares. It happens every day, and something slips through.`}}],set:[`feiltyper-lost`]},{id:`mange`,question:{nb:`Hvorfor er mange avskrifter bedre enn én?`,en:`Why are many copies better than one?`},clues:[`laeregutt`,`notat`,`iliader`,`brev`],steps:[{ask:{nb:`Hva sa læregutten, og hva står i notatet mitt?`,en:`What did the apprentice say, and what is in my note?`},clues:[`laeregutt`,`notat`],yes:{nb:`Feilen hans ble funnet mot en annen avskrift. Hva så du i boklageret?`,en:`His mistake was found against another copy. What did you see in the book storeroom?`},no:{nb:`Det er ikke læregutten eller notatet.`,en:`That is not the apprentice or the note.`}},{ask:{nb:`Hva så du blant Iliadene og brevet?`,en:`What did you see among the Iliads and the letter?`},clues:[`iliader`,`brev`],yes:{nb:`To mot én, og et brev i mange byer på en gang. Hvorfor er mange bedre?`,en:`Two against one, and a letter in many cities at once. Why are many better?`},no:{nb:`Det er ikke Iliadene eller brevet.`,en:`That is not the Iliads or the letter.`}}],options:[{text:{nb:`Ulike avskrivere på ulike steder gjør ulike feil, og feilen stikker ut mot de mange`,en:`Different copyists in different places make different slips; each stands out against the many`},feedback:{nb:`Riktig. Det som alt finnes i mange byer, kan ingen endre i stillhet. Hundre avskrifter fra hundre byer blir ikke enige om samme løgn.`,en:`Right. What already exists in many cities nobody can change quietly. A hundred copies from a hundred cities do not agree on the same lie.`},correct:!0},{text:{nb:`Fordi den nyeste alltid er best; hver avskriver retter feilene til den forrige`,en:`Because the newest is always best; each copyist corrects the mistakes of the one before`},feedback:{nb:`Nei. Den nyeste har flest ledd bak seg, og hver avskriver kan legge til feil. Det er antallet og spredningen som teller, ikke alderen alene.`,en:`No. The newest has the most links behind it, and each copyist can add mistakes. It is the number and the spread that count, not age alone.`}},{text:{nb:`Det er ikke bedre; feilene legger seg sammen for hver avskrift, så hundre avskrifter er hundre ganger verre`,en:`It is not better; the mistakes add up with every copy, so a hundred copies are a hundred times worse`},feedback:{nb:`Nei, bare hvis alle kopierer den samme feilen. Det gjør de ikke når de sitter i hver sin by og kopierer hver sitt forelegg.`,en:`No, only if they all copy the same mistake. They do not, when they sit in different cities copying different exemplars.`}}],set:[`mange-lost`]},{id:`homer`,question:{nb:`Hva gjør de lærde i Alexandria, og hva kan vi lære av dem?`,en:`What do the scholars in Alexandria do, and what can we learn from them?`},clues:[`bokhandler`,`alexandria`,`iliader`],steps:[{ask:{nb:`Hva sa bokhandleren om Homer?`,en:`What did the bookseller say about Homer?`},clues:[`bokhandler`],yes:{nb:`Tre ulike Iliader, og lærde som sammenligner. Hva så du i boklageret?`,en:`Three different Iliads, and scholars who compare. What did you see in the book storeroom?`},no:{nb:`Det er ikke bokhandleren.`,en:`That is not the bookseller.`}},{ask:{nb:`Hva så du på Homer-rullene?`,en:`What did you see on the Homer scrolls?`},clues:[`alexandria`,`iliader`],yes:{nb:`Merker i margen, ikke sletting; to mot én. Hva lærer vi?`,en:`Marks in the margin, not deletion; two against one. What do we learn?`},no:{nb:`Det er ikke Homer-rullene.`,en:`Those are not the Homer scrolls.`}}],options:[{text:{nb:`De sammenligner avskrifter og merker det som er lagt til`,en:`They compare copies and mark what was added`},feedback:{nb:`Riktig. Samme håndverk kan brukes på det jeg skriver: samle, sammenligne, merke ærlig.`,en:`Right. The same craft can be used on what I write: gather, compare, mark honestly.`},correct:!0},{text:{nb:`De sletter linjene de tror er feil, så teksten blir ren igjen`,en:`They delete the lines they think are wrong, so the text comes out clean again`},feedback:{nb:`Nei. De sletter ikke; de merker i margen. En linje de tror er feil, kan vise seg å være riktig når en eldre avskrift dukker opp.`,en:`No. They do not delete; they mark in the margin. A line they think is wrong may turn out to be right when an older copy turns up.`}},{text:{nb:`De velger den eldste rullen og setter den over alle de andre, uten å sammenligne`,en:`They pick the oldest scroll and set it above all the others, without comparing`},feedback:{nb:`Nei. Den eldste kan også ha feil. De leter etter den gamle teksten ved å sammenligne mange, ikke ved å peke på én.`,en:`No. The oldest can have mistakes too. They look for the old text by comparing many, not by pointing at one.`}}],set:[`homer-lost`]},{id:`tellerne`,question:{nb:`Hvordan kopierer jødene loven, og hva betyr det for oss?`,en:`How do the Jews copy the law, and what does it mean for us?`},clues:[`rabbi`,`lovrull`,`papyrus`],steps:[{ask:{nb:`Hva sa rabbien, og hva så du på lovrullen?`,en:`What did the rabbi say, and what did you see on the law scroll?`},clues:[`rabbi`,`lovrull`],yes:{nb:`Skrivere som teller, og ingen rettelser. Hva så du om papyrus?`,en:`Scribes who count, and no corrections. What did you see about papyrus?`},no:{nb:`Det er ikke rabbien eller lovrullen.`,en:`That is not the rabbi or the law scroll.`}},{ask:{nb:`Hva så du om papyrus?`,en:`What did you see about papyrus?`},clues:[`papyrus`],yes:{nb:`Billig, lett, varer i ørkensand. Hva betyr det for oss?`,en:`Cheap, light, lasts in desert sand. What does it mean for us?`},no:{nb:`Det er ikke papyrusen.`,en:`That is not the papyrus.`}}],options:[{text:{nb:`Jødene gransker hver bokstav; vi skriver fortere, men får mange flere avskrifter`,en:`The Jews scrutinise every letter; we write faster, but make many more copies`},feedback:{nb:`Riktig. Begge veier bevarer en tekst, men vår krever sammenligning: det rette står der de eldste og mest spredte er enige.`,en:`Right. Both ways preserve a text, but ours needs comparing: the right reading stands where the oldest and most widespread agree.`},correct:!0},{text:{nb:`Jødenes måte er den eneste trygge; en tekst med mange småfeil kan ikke lenger brukes til noe`,en:`The Jews’ way is the only safe one; a text with many small mistakes can no longer be used for anything`},feedback:{nb:`Nei. Jødenes måte er god, men ikke den eneste. Mange avskrifter som kan sammenlignes, er også trygt, på en annen måte. Småfeilene finner man igjen mot de andre.`,en:`No. The Jews’ way is good, but not the only one. Many copies that can be compared are safe too, in another way. The small mistakes are found again against the others.`}},{text:{nb:`Papyrus gjør alt ubrukelig; om hundre år er hver eneste avskrift smuldret bort`,en:`Papyrus makes everything useless; in a hundred years every single copy will have crumbled away`},feedback:{nb:`Nei. Den varer kortere, men den er billig nok til at det blir mange, og nye avskrifter tas før de gamle smuldrer. Og i ørkenen varer den lenge.`,en:`No. It does not last as long, but it is cheap enough that there are many, and new copies are made before the old ones crumble. And in the desert it lasts long.`}}],set:[`tellerne-lost`]},{id:`husket`,question:{nb:`Hva med tiden før noe ble skrevet ned?`,en:`What about the time before anything was written down?`},clues:[`blind`,`brev`],steps:[{ask:{nb:`Hva sa den blinde om å huske?`,en:`What did the blind man say about remembering?`},clues:[`blind`],yes:{nb:`Høre, gjenta, og mange som kan det samme. Hva så du om Paulus’ brev?`,en:`Hear, repeat, and many who know the same. What did you see about Paul’s letter?`},no:{nb:`Det er ikke den blinde.`,en:`That is not the blind man.`}},{ask:{nb:`Hva så du om Paulus’ brev?`,en:`What did you see about Paul’s letter?`},clues:[`brev`],yes:{nb:`Det han selv fikk overlevert, ga han videre, og brevet spredte seg fort. Hva betyr det for tiden før?`,en:`What he received he handed on, and the letter spread fast. What does that mean for the time before?`},no:{nb:`Det er ikke Paulus’ brev.`,en:`That is not Paul’s letter.`}}],options:[{text:{nb:`Ordene gikk lenge fra munn til munn, i et folk som lærte utenat, der mange kunne det samme og rettet hverandre. Og tidlig ble noe skrevet ned, som Paulus’ brev`,en:`For a long time the words went from mouth to mouth, among a people who learned by heart, where many knew the same and corrected each other. And early on some was written down, like Paul’s letter`},feedback:{nb:`Riktig. Småting i rekkefølge og ordlyd kunne skifte; kjernen holdt. Det skrevne spredte seg fort, og vitnene lever ennå: hadde ordene skiftet mye, hadde de sagt fra.`,en:`Correct. Small things in order and wording could shift; the core held. The written word spread fast, and the witnesses are still alive: had the words shifted much, they would have said so.`},correct:!0},{text:{nb:`Alt ble glemt i løpet av tretti år og diktet opp igjen av folk som aldri hadde møtt ham`,en:`Everything was forgotten within thirty years and invented again by people who had never met him`},feedback:{nb:`Nei. Hør den blinde: samme ord i Kapernaum og Jerusalem. Og de som så, lever og kan rette.`,en:`No. Listen to the blind man: the same words in Capernaum and Jerusalem. And those who saw are alive and can correct.`}},{text:{nb:`Alt ble skrevet ned samme dag som det skjedde, så ingenting gikk muntlig`,en:`Everything was written down the same day it happened, so nothing at all went orally`},feedback:{nb:`Nei. Mye gikk muntlig først, i mange år. Men muntlig er ikke det samme som upålitelig, ikke her, ikke blant folk som kan Salmene utenat.`,en:`No. Much went orally first, for many years. But oral is not the same as unreliable, not here, not among people who know the Psalms by heart.`}}],set:[`husket-lost`]},{id:`veien`,question:{nb:`Hvordan finner man tilbake til det opprinnelige, steg for steg?`,en:`How does one find the way back to the original, step by step?`},clues:[`laeregutt`,`alexandria`,`notat`,`margnotat`],steps:[{ask:{nb:`Finn læregutten, merkene fra Alexandria, notatet mitt og margnotatet.`,en:`Find the apprentice, the marks from Alexandria, my note and the marginal note.`},clues:[`laeregutt`,`alexandria`,`notat`,`margnotat`],yes:{nb:`Hva gjør man først? Sett det i rekkefølge.`,en:`What does one do first? Put it in order.`},no:{nb:`Det hjelper ikke med rekkefølgen.`,en:`That does not help with the order.`}}],sequence:[{nb:`Samle så mange avskrifter som mulig, fra så mange steder som mulig`,en:`Gather as many copies as possible, from as many places as possible`},{nb:`Legg dem ved siden av hverandre og finn stedene der de spriker`,en:`Lay them side by side and find the places where they diverge`},{nb:`Spør hvilken lesning som forklarer de andre, og foretrekk det vanskelige, for avskrivere glatter ut`,en:`Ask which reading explains the others, and prefer the hard one, for copyists smooth things out`},{nb:`Merk i margen det som er usikkert, uten å slette`,en:`Mark in the margin what is uncertain, without deleting`},{nb:`Se at det som er usikkert, ikke rokker ved det som bærer`,en:`See that what is uncertain does not shake what bears the weight`}],explained:{nb:`Slik vil de gjøre med det jeg skriver, når jeg ikke lenger kan spørres.`,en:`That is what they will do with what I write, when I can no longer be asked.`},set:[`veien-lost`]}],objectives:[{text:{nb:`Snakk med Lukas`,en:`Talk to Luke`},doneBy:[`oppdrag`]},{text:{nb:`Snakk med avskriveren, læregutten, bokhandleren, den blinde og rabbien`,en:`Talk to the copyist, the apprentice, the bookseller, the blind man and the rabbi`},doneBy:[`spor:avskriver`,`spor:laeregutt`,`spor:bokhandler`,`spor:blind`,`spor:rabbi`]},{text:{nb:`Finn feilene i læreguttens avskrift, og se på papyrusbunten`,en:`Find the mistakes in the apprentice’s copy, and look at the papyrus bundle`},doneBy:[`spill-avskrift`,`spor:papyrus`]},{text:{nb:`Gå inn i skriverstua`,en:`Go into the copying room`},doneBy:[`spor:forelegg`,`spor:margnotat`,`spor:diktat`,`spor:notat`]},{text:{nb:`Gå inn i boklageret`,en:`Go into the book storeroom`},doneBy:[`spor:iliader`,`spor:alexandria`,`spor:lovrull`,`spor:brev`]},{text:{nb:`Løs sakene i vitneboka`,en:`Solve the cases in the notebook`},doneBy:[`feiltyper-lost`,`mange-lost`,`homer-lost`,`tellerne-lost`,`husket-lost`,`veien-lost`]},{text:{nb:`Gå tilbake til Lukas`,en:`Go back to Luke`},doneBy:[`avsluttet`]}],rewards:[{flag:`feiltyper-lost`,points:15,label:{nb:`Kjenn igjen feiltypene`,en:`Recognise the kinds of mistakes`}},{flag:`mange-lost`,points:20,label:{nb:`Forstå hvorfor mange er bedre`,en:`Understand why many are better`}},{flag:`homer-lost`,points:10,label:{nb:`Lær av Alexandria`,en:`Learn from Alexandria`}},{flag:`tellerne-lost`,points:10,label:{nb:`Sammenlign med tellerne`,en:`Compare with the counters`}},{flag:`husket-lost`,points:15,label:{nb:`Forstå den muntlige tiden`,en:`Understand the oral period`}},{flag:`veien-lost`,points:10,label:{nb:`Finn veien tilbake`,en:`Find the way back`}},{flag:`avsluttet`,points:10,label:{nb:`Fullfør dagen med Lukas`,en:`Finish the day with Luke`}},{flag:`spill-avskrift`,points:10,label:{nb:`Finn de endrede ordene`,en:`Find the changed words`},side:!0},{flag:`spor:soldat`,points:5,label:{nb:`Hør om ordren som mistet «ikke»`,en:`Hear about the order that lost “not”`},side:!0},{flag:`spor:papyrus`,points:5,label:{nb:`Se papyrusbunten`,en:`See the papyrus bundle`},side:!0},{flag:`avskrift-levert`,points:12,label:{nb:`Skaff bokhandleren en avskrift av Paulus’ brev`,en:`Get the bookseller a copy of Paul’s letter`},side:!0},{flag:`ordrene-sammenlignet`,points:10,label:{nb:`Finn soldatens to ordretavler og sammenlign dem`,en:`Find the soldier’s two order tablets and compare them`},side:!0},{flag:`seglet-trykket`,points:10,label:{nb:`Sett seglet på avskriften`,en:`Seal the copy`},side:!0}],inventory:[{icon:`📄`,label:{nb:`Papyrus og avskrift`,en:`Papyrus and copy`},flags:[`ark`,`avskrift`],goneWhen:`avskrift-levert`}],ambience:[{sound:`sea`,x:8,y:16,radius:8},{sound:`sea`,x:16,y:16,radius:8},{sound:`sea`,x:23,y:16,radius:8},{sound:`market`,x:12,y:4,radius:5},{sound:`market`,x:21,y:6,radius:5},{sound:`market`,x:15,y:8,radius:4}],goal:[`avsluttet`],solution:`lukas.avskriver.laeregutt.laeregutt.bokhandler.blind.rabbi.jente.soldat.ordre-original.ordre-kopi.soldat.papyrus.avskriver.avskriver.bokhandler.dor-skriverstue.forelegg.margnotat.diktat.notat.dor-ut-skriverstue.dor-boklager.iliader.alexandria.lovrull.brev.dor-ut-boklager.feiltyper.mange.homer.tellerne.husket.veien.lukas`.split(`.`)};export{e as default};